import { edit_visit_locations } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    locationdeletion: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      loading: false
    };
  },
  watch: {
    locationdeletion: {
      async handler() {},
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(edit_visit_locations, {
          input: {
            location_id: this.rowInfo.location_id,
            location_status: "DEACTIVE"
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.edit_visit_locations);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
